import { pluginPartSchemas } from '../src/plugins/plugin-part-schemas';
import type { WirePartDefinition } from '../src/plugins/wire-parts';
import { accessibilitySection } from './plugin-reference-accessibility';
import {
  partDefinition,
  propsSchema,
  propsTable,
} from './plugin-reference-format';
import { slotTable } from './plugin-reference-slots';
import { versionNote } from './plugin-reference-version';

const generatedNote =
  '<!-- Generated by packages/contracts/tools/generate-plugin-reference.mts. Do not edit by hand. -->';

function colorRule(name: string, part: WirePartDefinition): string {
  return propsSchema(name).properties?.color
    ? part.reference.appearance
    : 'This schema does not declare a `color` prop; use the part’s documented semantic tokens.';
}

function imageRule(name: string, part: WirePartDefinition): string {
  return name === 'Image'
    ? part.reference.appearance
    : 'This part does not declare a direct Image prop. Image Slots use the Image part’s source and appearance rules.';
}

function eventNote(name: string, event: string): string {
  const description = eventDescription(name, event);

  return `- \`${event}\`: ${description}`;
}

function eventPropertyDescription(
  name: string,
  event: string,
): string | undefined {
  const schema = propsSchema(name).properties?.[event];

  return typeof schema === 'object' ? schema.description : undefined;
}

function eventDescription(name: string, event: string): string {
  return (
    eventPropertyDescription(name, event) ??
    'Payload is defined by the event schema.'
  );
}

function eventNotes(name: string, part: WirePartDefinition): string {
  const events = Object.keys(part.events);

  return events.length
    ? events.map((event) => eventNote(name, event)).join('\n')
    : 'This part defines no events.';
}

function deprecation(part: WirePartDefinition): string {
  return part.reference.deprecated ?? 'None.';
}

const code = (type: string): string => `\`${type}\``;

function childrenNote(part: WirePartDefinition): string {
  if (part.children === true) return 'Accepts child parts in source order.';

  if (!part.children) return 'Does not accept child nodes on the wire.';

  return `Accepts ${part.children.map(code).join(', ')} children in source order.`;
}

function sdkPropNote(part: WirePartDefinition): string {
  return part.reference.sdkProps ? `\n${part.reference.sdkProps}` : '';
}

function appearanceSection(name: string, part: WirePartDefinition): string {
  return [
    `- **Dark mode and color:** ${colorRule(name, part)}`,
    `- **Images:** ${imageRule(name, part)}`,
  ].join('\n');
}

function releaseSection(name: string, part: WirePartDefinition): string {
  return [
    `- **Deprecation:** ${deprecation(part)}`,
    `- **Version:** ${versionNote(name)}`,
  ].join('\n');
}

function propsSection(name: string): string {
  return `## Props\n\n${propsTable(name).trimEnd()}`;
}

function slotsSection(name: string, part: WirePartDefinition): string {
  const body = `${slotTable(name).trimEnd()}\n\n${childrenNote(part)}${sdkPropNote(part)}`;

  return `## Slots\n\n${body}`;
}

function partSections(name: string, part: WirePartDefinition): string[] {
  return [
    generatedNote,
    `# ${name}`,
    part.reference.summary,
    propsSection(name),
    slotsSection(name, part),
    `## Accessibility\n\n${accessibilitySection(name, part)}`,
    `## Appearance\n\n${appearanceSection(name, part)}`,
    `## Events\n\n${eventNotes(name, part)}`,
    `## Deprecation and version\n\n${releaseSection(name, part)}`,
  ];
}

export function renderPart(name: string): string {
  const part = partDefinition(name);

  return `${partSections(name, part).join('\n\n')}\n`;
}

export function renderIndex(names: string[]): string {
  const rows = names.map((name) => {
    const summary = partDefinition(name).reference.summary;

    return `| [\`${name}\`](./${name}.md) | ${summary} |`;
  });

  return `${generatedNote}

# Plugin part reference

Generated from the part prop schemas and metadata in Contracts. Each page documents serialized props, accepted Slots, accessibility behavior, appearance, events, and version notes.

The reference catalog includes shipped wire parts and Plugin-tier contracts recorded in the kit catalog. Pages are generated from Contracts schemas and metadata; they do not imply that a part is already available in every App version.

| Part | Summary |
| --- | --- |
${rows.join('\n')}
`;
}

export const partNames = Object.keys(pluginPartSchemas).sort();
